function_name='UART_EndRxTransfer' replacement_code="/**
* @brief  End ongoing Rx transfer on UART peripheral (following error detection or Reception completion).
* @param  huart UART handle.
* @retval None
*/
static void UART_EndRxTransfer(UART_HandleTypeDef *huart)
{
  /* In emulation, we don't have actual hardware registers to disable interrupts */
  /* Skip the MMIO operations for CR1 and CR3 register access */

  /* In case of reception waiting for IDLE event, disable also the IDLE IE interrupt source */
  if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
  {
    /* Skip MMIO operation for IDLEIE bit clearing */
  }

  /* At end of Rx process, restore huart->RxState to Ready */
  huart->RxState = HAL_UART_STATE_READY;
  huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;
}" reason='Fixed IRQ-type function by removing MMIO operations that access hardware registers (CR1, CR3). Preserved state management logic (RxState and ReceptionType updates) which is essential for upper-layer functionality. This prevents the "exceptional loop" error during emulation while maintaining correct state transitions.'
